import java.util.*;

class Solution {
  public NodeCopy copyRandomBinaryTree(Node root) {
    return copy(root, new HashMap<>());
  }

  private NodeCopy copy(Node node, Map<Node, NodeCopy> made) {
    if (node == null) return null;
    NodeCopy existing = made.get(node);
    if (existing != null) return existing;
    NodeCopy c = new NodeCopy(node.val);
    made.put(node, c); // register first: random pointers can form cycles
    c.left = copy(node.left, made);
    c.right = copy(node.right, made);
    c.random = copy(node.random, made);
    return c;
  }
}
